//! Plays the water-drop sounds through the operating system, not through the web view.
//! Web audio in a hidden window is unreliable, and this way the sound still
//! plays when the popup is on another screen or the app is in the background.
//! The sounds are generated by scripts/generate-drops.py and compiled into the app.

use std::thread;

/// The sound with this name, or the first one if the name is unknown.
fn wav(name: &str) -> &'static [u8] {
    match name {
        "bloop" => include_bytes!("../assets/drops/bloop.wav"),
        "plink" => include_bytes!("../assets/drops/plink.wav"),
        "pond" => include_bytes!("../assets/drops/pond.wav"),
        "twin" => include_bytes!("../assets/drops/twin.wav"),
        "glass" => include_bytes!("../assets/drops/glass.wav"),
        "cave" => include_bytes!("../assets/drops/cave.wav"),
        "tiny" => include_bytes!("../assets/drops/tiny.wav"),
        "leaf" => include_bytes!("../assets/drops/leaf.wav"),
        "bubble" => include_bytes!("../assets/drops/bubble.wav"),
        _ => include_bytes!("../assets/drops/drip.wav"),
    }
}

/// Starts the named sound and returns immediately.
pub fn play(name: &str) {
    let data = wav(name);
    thread::spawn(move || play_blocking(data));
}

#[cfg(target_os = "macos")]
fn play_blocking(data: &'static [u8]) {
    use std::{
        fs,
        process::Command,
        sync::atomic::{AtomicU32, Ordering},
    };

    // macOS keeps temp files in a per-user folder. A counter keeps two quick plays from sharing a file.
    static NEXT: AtomicU32 = AtomicU32::new(0);
    let id = NEXT.fetch_add(1, Ordering::Relaxed) % 4;
    let path = std::env::temp_dir().join(format!("little-interruptions-{id}.wav"));
    if fs::write(&path, data).is_err() {
        return;
    }
    let _ = Command::new("/usr/bin/afplay").arg(&path).status();
}

#[cfg(target_os = "windows")]
fn play_blocking(data: &'static [u8]) {
    #[link(name = "winmm")]
    extern "system" {
        fn PlaySoundW(sound: *const u16, module: *mut core::ffi::c_void, flags: u32) -> i32;
    }

    const SND_SYNC: u32 = 0x0000;
    const SND_MEMORY: u32 = 0x0004;

    // SAFETY: with SND_MEMORY the pointer is read as a WAV image; `data` is
    // 'static, and SND_SYNC keeps this thread inside the call until playback ends.
    unsafe {
        PlaySoundW(
            data.as_ptr().cast::<u16>(),
            core::ptr::null_mut(),
            SND_MEMORY | SND_SYNC,
        );
    }
}

#[cfg(not(any(target_os = "macos", target_os = "windows")))]
fn play_blocking(data: &'static [u8]) {
    use std::{fs, process::Command};

    let path = std::env::temp_dir().join("little-interruptions-sound.wav");
    if fs::write(&path, data).is_ok() {
        let _ = Command::new("aplay").arg("-q").arg(&path).status();
    }
}

#[cfg(test)]
mod tests {
    use super::wav;

    #[test]
    fn every_sound_is_a_wav_and_unknown_names_fall_back() {
        for name in [
            "drip", "bloop", "plink", "pond", "twin", "glass", "cave", "tiny", "leaf", "bubble",
        ] {
            let data = wav(name);
            assert_eq!(&data[..4], b"RIFF", "{name}");
            assert_eq!(&data[8..12], b"WAVE", "{name}");
        }
        assert_eq!(wav("nope"), wav("drip"));
        assert_ne!(wav("bloop"), wav("drip"));
    }
}
